__modules["Colors"] = function()
--[[
	Colors: every colour in the template is fully saturated (QM: "top right of
	the colour picker square, only the hue changes").

	UI colours are hue(h): saturation 1, value 1.
	World colours keep saturation 1 and only lower the value where a material
	must read darker than its neighbours (dirt, trunks, leaves against grass).
	Change a value here to recolour the whole map.
]]

local Colors = {}

function Colors.hue(h: number, v: number?): Color3
	return Color3.fromHSV((h % 360) / 360, 1, v or 1)
end

local hue = Colors.hue

-- Spawn area and the walls shared by every biome
Colors.Map = {
	SpawnGround = hue(95, 0.85),
	Dirt = hue(22, 0.55),
	Grass = hue(100, 0.8),
	HitZone = hue(50, 1),
	Line = Color3.new(1, 1, 1), -- the glowing edge of the hit zone
}

-- flower heads scattered on the lane edges
Colors.Flowers = { hue(0, 1), hue(50, 1), hue(300, 1), hue(200, 1) }

-- One entry per biome, in the order they run out from the hit zone.
Colors.Biomes = {
	Forest = {
		Ground = hue(115, 0.75),
		Dirt = hue(22, 0.5),
		Grass = hue(115, 0.65),
		Trunk = hue(20, 0.45),
		Leaves = { hue(125, 0.6), hue(110, 0.7), hue(135, 0.52) },
		Sign = hue(120, 1),
	},
	Savanna = {
		Ground = hue(45, 0.9),
		Dirt = hue(25, 0.6),
		Grass = hue(55, 0.85),
		Trunk = hue(22, 0.42),
		Leaves = { hue(85, 0.62), hue(75, 0.68), hue(95, 0.55) },
		Sign = hue(40, 1),
	},
}

return Colors

end

__modules["Map"] = function()
--[[
	Map: the reusable map template.

	Layout (X is the throw direction, Y up):
	  - Spawn: a 3:1 rectangle of native baseplate ground, walled in with dirt.
	  - The long +X wall opens onto the world through a gap as wide as the
	    biome lane (QM). Through it: a glowing white line, then the hit zone, a
	    thin yellow strip with big "HIT ZONE" text. Past the strip the ground
	    steps down a few studs (Settings.Drop).
	  - The biomes run out one after another along +X, each Settings.BiomeLength
	    long, between terraced dirt walls (Settings.Terraces): blocky steps with
	    grass lips and trees on every step, then a tall back wall; bushes and
	    flowers line the lane edges (QM's reference, 2026-11-12).

	Map.build() makes Workspace.Map. Gameplay code can read:
	  Map.HitZone (part, attribute HitZone = true)
	  Map.Biomes.<Name>.Ground (attributes Biome, StartX, EndX)
]]

local Workspace = game:GetService("Workspace")
local ServerStorage = game:GetService("ServerStorage")

local Builder = __require("Builder")
local Palette = __require("Palette")
local Colors = __require("Colors")
local Trees = __require("Trees")

local Map = {}

local V3 = Vector3.new

Map.Settings = {
	SpawnDepth = 80, -- short side (X)
	SpawnLength = 240, -- long side (Z), 3:1
	WallHeight = 14,
	WallThickness = 4,
	GrassCap = 2,
	GapWidth = 120, -- the opening in the long wall: as wide as the lane (QM)
	HitZoneDepth = 12, -- thin strip (QM)
	LineWidth = 1.5, -- glowing line just before the strip, on the spawn side
	Drop = 4, -- small step from the hit zone down to the biomes (QM: barely any)
	LaneWidth = 120, -- = GapWidth
	-- biome walls: terraces stepping up and away from the lane (QM's reference),
	-- each cut into segments whose height jitters a little for a blocky skyline,
	-- trees on every step, then a tall back wall
	Terraces = {
		{ Width = 16, Height = 8, Trees = 9 },
		{ Width = 16, Height = 18, Trees = 7 },
		{ Width = 16, Height = 30, Trees = 6 },
	},
	BackWallHeight = 44,
	TerraceSegment = 50,
	TerraceJitter = 3,
	GrassOverhang = 1, -- grass caps lip out over the step below
	Bushes = 26, -- per biome, along the lane edges
	Flowers = 40, -- per biome, tiny two-block flowers on the lane edges
	BiomeLength = 500,
	TreesPerBiome = 26,
	ClearPath = 20, -- no trees within this many studs of the centre line
	Biomes = { "Forest", "Savanna" },
	-- turns the HIT ZONE text so it reads from the spawn side
	TextRotation = 180,
}

-- Part from two corners (min, max) in world space.
local function slab(parent: Instance, name: string, a: Vector3, b: Vector3, color: Color3, style, opts)
	local lo = a:Min(b)
	local hi = a:Max(b)
	opts = opts or {}
	opts.name = name
	return Builder.part(parent, hi - lo, CFrame.new((lo + hi) / 2), color, style, opts)
end

-- Dirt wall with a grass cap, both in the terrain style (native grid + studs).
-- lip: the cap sticks out this far past z0 (negative) or z1 (positive)
local function wall(parent: Instance, name: string, x0, z0, x1, z1, yBottom: number, yTop: number, pal, lip: number?)
	local cap = Map.Settings.GrassCap
	local m = Builder.model(name, parent)
	slab(m, "Dirt", V3(x0, yBottom, z0), V3(x1, yTop - cap, z1), pal.Dirt, "terrain")
	local gz0, gz1 = z0, z1
	if lip and lip < 0 then
		gz0 += lip
	elseif lip and lip > 0 then
		gz1 += lip
	end
	slab(m, "Grass", V3(x0, yTop - cap, gz0), V3(x1, yTop, gz1), pal.Grass, "terrain")
	return m
end

-- KISS bush: a big leaf block with a smaller one on top
local function bush(parent: Instance, at: Vector3, w: number, color: Color3, rot: number)
	local m = Builder.model("Bush", parent)
	local cf = CFrame.new(at) * CFrame.Angles(0, rot, 0)
	local h = w * 0.55
	Builder.part(m, V3(w, h, w * 0.8), cf * CFrame.new(0, h / 2, 0), color, "studs", { name = "Big" })
	Builder.part(m, V3(w * 0.65, h * 0.5, w * 0.55), cf * CFrame.new(0, h * 1.25, 0), color, "studs", { name = "Top" })
	return m
end

-- KISS flower: one stem block, one head block
local function flower(parent: Instance, at: Vector3, stem: Color3, head: Color3)
	local m = Builder.model("Flower", parent)
	Builder.part(m, V3(0.4, 1.6, 0.4), CFrame.new(at + V3(0, 0.8, 0)), stem, "smooth", { name = "Stem", canCollide = false })
	Builder.part(m, V3(1.2, 0.8, 1.2), CFrame.new(at + V3(0, 1.9, 0)), head, "studs", { name = "Head", canCollide = false })
	return m
end

-- The place's own Baseplate is the template for every piece of ground (QM:
-- native baseplate, recoloured). It is kept in ServerStorage.TemplateSource.
local function baseplateSource(): BasePart?
	local store = ServerStorage:FindFirstChild("TemplateSource")
	local bp = store and store:FindFirstChild("Baseplate")
	if not bp then
		bp = Workspace:FindFirstChild("Baseplate")
	end
	return if bp and bp:IsA("BasePart") then bp else nil
end

local function ground(parent: Instance, name: string, x0, z0, x1, z1, topY: number, color: Color3)
	local src = baseplateSource()
	local p: BasePart
	if src then
		p = src:Clone()
		for _, c in p:GetChildren() do
			if not c:IsA("Texture") then
				c.Parent = nil
			end
		end
		local tex = p:FindFirstChildOfClass("Texture")
		if tex then
			Builder.useGridFrom(tex)
			if tex.Transparency >= 1 then
				tex.Transparency = Palette.Baseplate.TextureTransparency
			end
		end
	else
		p = Instance.new("Part")
		p.Size = V3(1, Palette.Baseplate.Thickness, 1)
		Builder.baseplateTexture(p, Palette.Baseplate)
	end
	local thick = p.Size.Y
	p.Size = V3(math.abs(x1 - x0), thick, math.abs(z1 - z0))
	p.CFrame = CFrame.new((x0 + x1) / 2, topY - thick / 2, (z0 + z1) / 2)
	p.Color = color
	p.Material = Enum.Material.Plastic
	p.Reflectance = 0
	p.Transparency = 0
	p.Anchored = true
	p.CanCollide = true
	p.Locked = false
	p.TopSurface = Enum.SurfaceType.Smooth
	p.Name = name
	p.Parent = parent
	return p
end

local function text(parent: Instance, t: string, size: UDim2, order: number)
	local l = Instance.new("TextLabel")
	l.BackgroundTransparency = 1
	l.Size = size
	l.Font = Enum.Font.FredokaOne
	l.Text = t
	l.TextScaled = true
	l.TextColor3 = Color3.new(1, 1, 1)
	l.LayoutOrder = order
	l.Parent = parent
	return l
end

-- "HIT ZONE" painted across the strip, as big as it fits
local function hitZoneText(hz: BasePart)
	local S = Map.Settings
	-- a flat carrier part, turned so the text reads from the spawn side
	-- a Top-face SurfaceGui runs its width along the part's local Z, so the
	-- long side goes on Z when the rotation is 0/180 and on X when it is 90/270
	local across, along = hz.Size.Z - 2, hz.Size.X - 1
	local size = if S.TextRotation % 180 == 0 then V3(along, 0.05, across) else V3(across, 0.05, along)
	local carrier = Builder.part(hz.Parent :: Instance, size,
		hz.CFrame * CFrame.new(0, hz.Size.Y / 2 + 0.03, 0) * CFrame.Angles(0, math.rad(S.TextRotation), 0),
		Color3.new(1, 1, 1), "smooth", { name = "HitZoneText", canCollide = false, castShadow = false, transparency = 1 })
	carrier.CanQuery = false
	carrier.CanTouch = false
	local gui = Instance.new("SurfaceGui")
	gui.Name = "Text"
	gui.Face = Enum.NormalId.Top
	gui.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud
	gui.PixelsPerStud = 8 -- low on purpose: TextScaled tops out at 100 px, so this keeps the words big
	gui.LightInfluence = 1
	gui.Parent = carrier
	local word = text(gui, "HIT ZONE", UDim2.fromScale(0.97, 0.94), 1)
	word.AnchorPoint = Vector2.new(0.5, 0.5)
	word.Position = UDim2.fromScale(0.5, 0.5)
	local stroke = Instance.new("UIStroke")
	stroke.Thickness = 4
	stroke.Color = Color3.new(0, 0, 0)
	stroke.LineJoinMode = Enum.LineJoinMode.Round
	stroke.Parent = word
	return carrier
end

local function sign(parent: Instance, name: string, at: Vector3, color: Color3)
	local anchor = Builder.part(parent, V3(1, 1, 1), CFrame.new(at), color, "smooth",
		{ name = name .. "Sign", canCollide = false, castShadow = false, transparency = 1 })
	anchor.CanQuery = false
	anchor.CanTouch = false
	local gui = Instance.new("BillboardGui")
	gui.Size = UDim2.fromScale(80, 20) -- studs, so it shrinks with distance
	gui.MaxDistance = 2000
	gui.LightInfluence = 0
	gui.Parent = anchor
	local l = text(gui, name, UDim2.fromScale(1, 1), 1)
	l.TextColor3 = color
	local stroke = Instance.new("UIStroke")
	stroke.Thickness = 4
	stroke.Color = Color3.new(0, 0, 0)
	stroke.Parent = l
	return anchor
end

function Map.build(parent: Instance?)
	local S = Map.Settings
	parent = parent or Workspace
	local old = (parent :: Instance):FindFirstChild("Map")
	if old then
		old.Parent = nil
	end
	local root = Builder.model("Map", parent)
	local C = Colors.Map
	local wallPal = { Dirt = C.Dirt, Grass = C.Grass }

	local D, L, H, t = S.SpawnDepth, S.SpawnLength, S.WallHeight, S.WallThickness
	local G, HZ, Drop, W = S.GapWidth, S.HitZoneDepth, S.Drop, S.LaneWidth
	local terraceWidth = 0
	for _, tr in S.Terraces do
		terraceWidth += tr.Width
	end
	local outerZ = W / 2 + terraceWidth + t -- outer Z of the biome walls
	local edgeZ = math.max(L / 2 + t, outerZ) -- outer Z of the spawn and cliff

	----------------------------------------------------------------- spawn
	local spawnM = Builder.model("Spawn", root)
	ground(spawnM, "Ground", -D - t, -L / 2 - t, 0, L / 2 + t, 0, C.SpawnGround)
	wall(spawnM, "BackWall", -D - t, -L / 2 - t, -D, L / 2 + t, 0, H, wallPal)
	wall(spawnM, "SideWallLeft", -D, -L / 2 - t, 0, -L / 2, 0, H, wallPal)
	wall(spawnM, "SideWallRight", -D, L / 2, 0, L / 2 + t, 0, H, wallPal)
	wall(spawnM, "FrontWallLeft", 0, -L / 2 - t, t, -G / 2, 0, H, wallPal)
	wall(spawnM, "FrontWallRight", 0, G / 2, t, L / 2 + t, 0, H, wallPal)
	-- the place's SpawnLocation, made invisible and moved to the back of the spawn
	local sp = Workspace:FindFirstChildOfClass("SpawnLocation")
	if not sp then
		sp = Instance.new("SpawnLocation")
		sp.Parent = Workspace
	end
	sp.Anchored = true
	sp.Size = V3(12, 1, 12)
	-- players spawn facing +X, at the gap and the hit zone (a SpawnLocation's front is -Z)
	sp.CFrame = CFrame.new(-D + 14, -0.45, 0) * CFrame.Angles(0, -math.pi / 2, 0)
	sp.Transparency = 1
	sp.CanCollide = false
	sp.Neutral = true
	for _, d in sp:GetChildren() do
		if d:IsA("Decal") then
			d.Transparency = 1
		end
	end

	--------------------------------------------------------------- hit zone
	local hzM = Builder.model("HitZone", root)
	-- gap floor (under the front wall), then the glowing line, then the strip
	local lx0, lx1 = t, t + S.LineWidth
	local x1 = lx1 + HZ
	ground(hzM, "GapFloor", 0, -G / 2, t, G / 2, 0, C.SpawnGround)
	local hz = slab(hzM, "Zone", V3(lx1, -1, -G / 2), V3(x1, 0, G / 2), C.HitZone, "terrain")
	hz:SetAttribute("HitZone", true)
	slab(hzM, "LineBed", V3(lx0, -1, -G / 2), V3(lx1, 0, G / 2), C.HitZone, "terrain")
	-- the small step down to the lane, and the walls either side of the opening
	slab(hzM, "StepFace", V3(0, -Drop, -G / 2), V3(x1, -1, G / 2), C.Dirt, "terrain")
	if edgeZ > G / 2 then
		wall(hzM, "CliffLeft", t, -edgeZ, x1, -G / 2, -Drop, H, wallPal)
		wall(hzM, "CliffRight", t, G / 2, x1, edgeZ, -Drop, H, wallPal)
		slab(hzM, "WallFootLeft", V3(0, -Drop, -edgeZ), V3(t, 0, -G / 2), C.Dirt, "terrain")
		slab(hzM, "WallFootRight", V3(0, -Drop, G / 2), V3(t, 0, edgeZ), C.Dirt, "terrain")
	end
	local line = slab(hzM, "GlowLine", V3(lx0, 0, -G / 2), V3(lx1, 0.2, G / 2), C.Line, "smooth",
		{ material = Enum.Material.Neon, canCollide = false, castShadow = false })
	local light = Instance.new("SurfaceLight")
	light.Face = Enum.NormalId.Top
	light.Color = C.Line
	light.Brightness = 2
	light.Range = 8
	light.Angle = 120
	light.Parent = line
	hitZoneText(hz)
	Map.HitZone = hz

	----------------------------------------------------------------- biomes
	local biomesM = Builder.model("Biomes", root)
	local laneStart = t + S.LineWidth + HZ
	local laneEnd = laneStart + #S.Biomes * S.BiomeLength
	Map.Biomes = {}
	for i, name in S.Biomes do
		local pal = Colors.Biomes[name]
		local bx0 = laneStart + (i - 1) * S.BiomeLength
		local bx1 = bx0 + S.BiomeLength
		local bm = Builder.model(name, biomesM)
		local g = ground(bm, "Ground", bx0, -outerZ, bx1, outerZ, -Drop, pal.Ground)
		g:SetAttribute("Biome", name)
		g:SetAttribute("StartX", bx0)
		g:SetAttribute("EndX", bx1)
		local wp = { Dirt = pal.Dirt, Grass = pal.Grass }
		local rng = Random.new(1000 + i)
		local decor = Builder.model("Trees", bm)
		local walls = Builder.model("Terraces", bm)
		sign(bm, name, V3(bx0 + 70, -Drop + 46, 0), pal.Sign)

		-- terraces: segments with jittered heights, trees on top of each
		for _, side in { -1, 1 } do
			local zIn = W / 2
			for ti, tr in S.Terraces do
				local zOut = zIn + tr.Width
				local x = bx0
				local seg = 0
				while x < bx1 - 0.01 do
					seg += 1
					local len = math.min(S.TerraceSegment + rng:NextInteger(-12, 12), bx1 - x)
					local top = -Drop + tr.Height + rng:NextInteger(-S.TerraceJitter, S.TerraceJitter)
					local a0, a1 = side * zIn, side * zOut
					wall(walls, ("T%d_%s_%d"):format(ti, if side < 0 then "L" else "R", seg),
						x, math.min(a0, a1), x + len, math.max(a0, a1), -Drop, top, wp,
						-side * S.GrassOverhang)
					x += len
				end
				for k = 1, tr.Trees do
					local tx = bx0 + (k - 0.5) * S.BiomeLength / tr.Trees + rng:NextNumber(-12, 12)
					local tz = side * (zIn + tr.Width / 2 + rng:NextNumber(-2, 2))
					-- stand it on whichever segment is under it
					local hit = workspace:Raycast(V3(tx, 200, tz), V3(0, -400, 0), (function()
						local rp = RaycastParams.new()
						rp.FilterType = Enum.RaycastFilterType.Include
						rp.FilterDescendantsInstances = { walls }
						return rp
					end)())
					local ty = if hit then hit.Position.Y else -Drop + tr.Height
					local cf = CFrame.new(tx, ty, tz) * CFrame.Angles(0, rng:NextNumber(0, math.pi * 2), 0)
					Trees.build(name, decor, cf, pal, rng)
				end
				zIn = zOut
			end
			local zb = W / 2 + terraceWidth
			wall(walls, "Back" .. (if side < 0 then "L" else "R"), bx0, math.min(side * zb, side * outerZ), bx1,
				math.max(side * zb, side * outerZ), -Drop, -Drop + S.BackWallHeight, wp)
		end

		-- lane floor: trees near the walls, the centre clear for the ragdoll
		local n = S.TreesPerBiome
		for k = 1, n do
			local x = bx0 + 14 + (k - 0.5) * (S.BiomeLength - 28) / n + rng:NextNumber(-6, 6)
			local side = if k % 2 == 0 then 1 else -1
			local z = side * rng:NextNumber(S.ClearPath + 10, W / 2 - 8)
			local cf = CFrame.new(x, -Drop, z) * CFrame.Angles(0, rng:NextNumber(0, math.pi * 2), 0)
			Trees.build(name, decor, cf, pal, rng)
		end
		local deco = Builder.model("Decor", bm)
		for k = 1, S.Bushes do
			local x = bx0 + rng:NextNumber(6, S.BiomeLength - 6)
			local side = if k % 2 == 0 then 1 else -1
			local z = side * rng:NextNumber(S.ClearPath, W / 2 - 3)
			bush(deco, V3(x, -Drop, z), rng:NextNumber(4, 7), pal.Leaves[rng:NextInteger(1, #pal.Leaves)], rng:NextNumber(0, math.pi))
		end
		for k = 1, S.Flowers do
			local x = bx0 + rng:NextNumber(4, S.BiomeLength - 4)
			local side = if k % 2 == 0 then 1 else -1
			local z = side * rng:NextNumber(S.ClearPath - 6, W / 2 - 2)
			local heads = Colors.Flowers
			flower(deco, V3(x, -Drop, z), pal.Grass, heads[rng:NextInteger(1, #heads)])
		end
		Map.Biomes[name] = { Model = bm, Ground = g, StartX = bx0, EndX = bx1 }
	end
	wall(biomesM, "EndWall", laneEnd, -outerZ, laneEnd + t, outerZ, -Drop, -Drop + S.BackWallHeight, wallPal)

	Map.Model = root
	return root
end

return Map

end

__modules["Sky"] = function()
--[[
	Sky: puts the free "Cartoon Sky" skybox (asset 10594688909) from the Creator Store into Lighting.

	Only the Sky instance is taken from the model, so no scripts come along.
	Sky.AssetId pins a specific asset; left nil, the first free model whose name
	has both "cartoon" and "sky" is used (the id is printed so it can be pinned).
]]

local InsertService = game:GetService("InsertService")
local LightingService = game:GetService("Lighting")

local Sky = {}

Sky.AssetId = 10594688909 :: number? -- "Cartoon Sky" (QM picked it, 2026-11-12)
Sky.Query = "Cartoon Sky"

function Sky.find(): (number?, string?)
	if Sky.AssetId then
		return Sky.AssetId, "pinned"
	end
	local ok, pages = pcall(function()
		return InsertService:GetFreeModels(Sky.Query, 0)
	end)
	if not ok or not pages or not pages[1] then
		return nil, nil
	end
	for _, r in pages[1].Results do
		local n = string.lower(r.Name)
		if string.find(n, "cartoon") and string.find(n, "sky") then
			return r.AssetId, r.Name .. " by " .. tostring(r.CreatorName)
		end
	end
	return nil, nil
end

function Sky.apply(): Sky?
	local id, label = Sky.find()
	if not id then
		warn("[Template] Cartoon Sky not found in the Creator Store; sky left as it was")
		return nil
	end
	local ok, objs = pcall(function()
		return game:GetObjects("rbxassetid://" .. id)
	end)
	if not ok or not objs then
		warn("[Template] could not load Cartoon Sky " .. tostring(id))
		return nil
	end
	local sky: Sky? = nil
	for _, o in objs do
		sky = if o:IsA("Sky") then o else o:FindFirstChildWhichIsA("Sky", true)
		if sky then
			break
		end
	end
	if not sky then
		warn("[Template] asset " .. tostring(id) .. " has no Sky in it")
		return nil
	end
	for _, old in LightingService:GetChildren() do
		if old:IsA("Sky") then
			old.Parent = nil
		end
	end
	sky.Name = "CartoonSky"
	sky.Parent = LightingService
	print(("[Template] sky: CartoonSky asset %d (%s)"):format(id, tostring(label)))
	return sky
end

return Sky

end

__modules["Trees"] = function()
--[[
	Trees: KISS block trees, a handful of variants per biome.

	One block per trunk or branch, foliage = one big block plus one slightly
	smaller block just above it. Every part is flat colour + QM's L-studs.
	Each builder takes (parent, origin CFrame on the ground, palette, rng)
	and returns a Model pivoted at the origin.
]]

local Builder = __require("Builder")

local Trees = {}

local V3 = Vector3.new

local function box(m: Model, origin: CFrame, center: Vector3, size: Vector3, color: Color3, name: string)
	return Builder.box(m, origin, center, size, color, "studs", { name = name })
end

-- One block running from local point a to local point b (branches, leaning trunks).
local function beam(m: Model, origin: CFrame, a: Vector3, b: Vector3, thick: number, color: Color3, name: string)
	local dir = b - a
	local up = if math.abs(dir.Unit.Y) > 0.99 then Vector3.xAxis else Vector3.yAxis
	local cf = CFrame.lookAt((a + b) / 2, b, up)
	return Builder.part(m, V3(thick, thick, dir.Magnitude), origin * cf, color, "studs", { name = name })
end

-- big block with its bottom at y, small block on top: reads as a rounded crown
local function crown(m: Model, origin: CFrame, at: Vector3, w: number, h: number, color: Color3, name: string)
	box(m, origin, at + V3(0, h / 2, 0), V3(w, h, w), color, name .. "Big")
	local sw = w * 0.7
	box(m, origin, at + V3(0, h + h * 0.25, 0), V3(sw, h * 0.5, sw), color, name .. "Top")
end

--------------------------------------------------------------------------------
-- Forest: regular trees
--------------------------------------------------------------------------------
Trees.Forest = {}

-- 1 classic: trunk + crown
Trees.Forest[1] = function(m, o, pal, leaves)
	box(m, o, V3(0, 6, 0), V3(3, 12, 3), pal.Trunk, "Trunk")
	crown(m, o, V3(0, 11, 0), 14, 8, leaves, "Leaves")
end

-- 2 tall and narrow
Trees.Forest[2] = function(m, o, pal, leaves)
	box(m, o, V3(0, 10, 0), V3(3, 20, 3), pal.Trunk, "Trunk")
	crown(m, o, V3(0, 19, 0), 11, 9, leaves, "Leaves")
end

-- 3 with one side branch carrying a small crown
Trees.Forest[3] = function(m, o, pal, leaves)
	box(m, o, V3(0, 7, 0), V3(3, 14, 3), pal.Trunk, "Trunk")
	beam(m, o, V3(0, 7, 0), V3(7, 12, 0), 2, pal.Trunk, "Branch")
	crown(m, o, V3(7, 11.5, 0), 8, 4, leaves, "BranchLeaves")
	crown(m, o, V3(0, 13, 0), 13, 7, leaves, "Leaves")
end

-- 4 short and wide
Trees.Forest[4] = function(m, o, pal, leaves)
	box(m, o, V3(0, 4, 0), V3(4, 8, 4), pal.Trunk, "Trunk")
	crown(m, o, V3(0, 7, 0), 18, 7, leaves, "Leaves")
end

--------------------------------------------------------------------------------
-- Savanna: acacias. Leaning trunk block, one block per branch, a flat slab
-- canopy (big slab + smaller slab above) at the end of each branch.
--------------------------------------------------------------------------------
Trees.Savanna = {}

local function slabCanopy(m, o, at: Vector3, w: number, d: number, color: Color3, name: string)
	box(m, o, at + V3(0, 0.8, 0), V3(w, 1.6, d), color, name .. "Big")
	box(m, o, at + V3(0, 2.2, 0), V3(w * 0.68, 1.2, d * 0.68), color, name .. "Top")
end

local function acacia(m, o, pal, leaves, lean: number, height: number, branches)
	local top = V3(lean, height, 0)
	beam(m, o, V3(0, -1, 0), top, 2.6, pal.Trunk, "Trunk")
	for i, b in branches do
		local tip = top + b.to
		-- start a little below the trunk top so the joint is buried
		beam(m, o, top - V3(0, 1, 0), tip, 1.8, pal.Trunk, "Branch" .. i)
		slabCanopy(m, o, tip - V3(0, 0.6, 0), b.w, b.d, leaves, "Canopy" .. i)
	end
end

-- 1 two branches
Trees.Savanna[1] = function(m, o, pal, leaves)
	acacia(m, o, pal, leaves, 2, 10, {
		{ to = V3(-6, 7, 2), w = 15, d = 12 },
		{ to = V3(7, 5, -3), w = 13, d = 11 },
	})
end

-- 2 three branches, wide
Trees.Savanna[2] = function(m, o, pal, leaves)
	acacia(m, o, pal, leaves, -2, 11, {
		{ to = V3(-7, 6, -2), w = 13, d = 11 },
		{ to = V3(6, 7, 4), w = 14, d = 12 },
		{ to = V3(1, 9, -6), w = 11, d = 10 },
	})
end

-- 3 one tall branch, single big canopy
Trees.Savanna[3] = function(m, o, pal, leaves)
	acacia(m, o, pal, leaves, 3, 13, {
		{ to = V3(2, 6, 0), w = 20, d = 16 },
	})
end

-- 4 short and leaning hard
Trees.Savanna[4] = function(m, o, pal, leaves)
	acacia(m, o, pal, leaves, 5, 7, {
		{ to = V3(4, 4, 1), w = 16, d = 13 },
		{ to = V3(-3, 6, -2), w = 10, d = 9 },
	})
end

function Trees.build(kind: string, parent: Instance, origin: CFrame, pal, rng: Random, variant: number?)
	local list = Trees[kind]
	local i = variant or rng:NextInteger(1, #list)
	local leaves = pal.Leaves[rng:NextInteger(1, #pal.Leaves)]
	local m = Builder.model(kind .. "Tree" .. i, parent, origin)
	list[i](m, origin, pal, leaves)
	return m
end

return Trees

end

__modules["UI"] = function()
--[[
	UI: HUD element templates copied from QM's Figma ("UI Templating" page,
	file BWrUjODdJ2oWVUYsdkZxyt). Sizes below are the Figma pixel sizes; the
	HUD's AutoScale shrinks everything to the screen.

	Face style (every coloured element): flat fill, 12px corners, 3px outline
	black at 50%, a shade gradient over the bottom, the stud texture tiled on
	top. Text is FredokaOne, white, with a dark outline.

	    local UIKit = require(game.ReplicatedStorage.UIKit)
	    UIKit.rectButton({ Text = "Shop", Icon = UIKit.Assets.Shop, Color = UIKit.Colors.Red })
	    UIKit.squareButton({ Icon = UIKit.Assets.Aura, Color = UIKit.Colors.Purple })
	    UIKit.counter({ Icon = UIKit.Assets.Trophy, Text = "5K", TextColor = UIKit.Colors.Gold })
	    local bar = UIKit.progress({ Level = 80, Value = "1.2k/3.05k", Fill = 0.4 })
	    UIKit.buyButton({ Text = "+10M", Color = UIKit.Colors.Yellow, Shade = UIKit.Colors.ShadeRed })
	    local modal, content = UIKit.modal({ Title = "Shop" })

	Popups: UI.popup (generic), UI.shopPopup, UI.rebirthPopup; UI.notification
	puts the red "!" dot on a button.
	Buttons with an "Opens" attribute toggle the popup/modal of that name (see the
	HUD's controller script); every modal's "Close" button hides it.
	Each button is a fixed slot with a centred "Visual" child that holds the
	face and content; hover/press scale only the Visual, so nothing moves.
	squareButton with no Color is the see-through Figma square.
]]

local UI = {}

UI.Font = Enum.Font.FredokaOne
UI.TextOutline = Color3.fromRGB(26, 16, 48)
-- Roblox draws FredokaOne about 20% smaller than Figma at the same size, so
-- every Figma text size is multiplied by this (measured against docs/figma)
UI.TextScale = 1.2
-- level bar width: 96px tall at 8:1 (QM); the buy buttons split the same width
UI.BarWidth = 768
-- In-game sizing, matched to QM's reference screenshot (docs/figma/layout_inspo.png,
-- 1994x1488): the HUD is drawn at Figma px for a screen RefHeight px tall, and
-- the bottom cluster / counters get their own extra scale so their on-screen
-- size matches the reference too.
UI.RefHeight = 1300
-- the HUD also shrinks on screens narrower than 1625:1300 (5:4), so the left
-- column and the bottom cluster never overlap; 16:9 and 4:3 are unchanged
UI.RefWidth = 1625

-- the HUD's AutoScale for a viewport (the controller uses the same formula)
function UI.fitScale(viewport: Vector2): number
	return math.clamp(math.min(viewport.Y / UI.RefHeight, viewport.X / UI.RefWidth), 0.3, 1.6)
end
UI.BottomScale = 0.945 -- bar 830 px wide on a 1488 px screen
UI.PopupScale = 1.15 -- popups ~57% of the screen height, as in QM's references
UI.CounterScale = 1.25 -- counter icons ~100 px on a 1488 px screen

-- Uploaded from the Figma file (rbxassetid). Empty = not uploaded yet.
UI.Assets = {
	Studs = "rbxassetid://115518459266095", -- stud tile used by rect / progress / buy buttons (89.4px tile, 40%)
	StudsSquare = "rbxassetid://135739892997443", -- stud texture on the square buttons (230px tile, 20%)
	Shop = "rbxassetid://105128988344580", -- basket
	Aura = "rbxassetid://87628923496008",
	Pet = "rbxassetid://75080514724176",
	Skill = "rbxassetid://89389357448559", -- small flexed arm
	Trophy = "rbxassetid://121674502856865",
	Rebirth = "rbxassetid://91294314164136",
	Muscle = "rbxassetid://89389357448559", -- big flexed arm on the buy buttons
}
-- Figma v2 (QM, Nov 12): new icons, uploaded at 512px (originals 1254px)
UI.Assets.Shop = "rbxassetid://94629817402467" -- basket v2
UI.Assets.Aura = "rbxassetid://122473751099925" -- blue flame aura
UI.Assets.Rebirth = "rbxassetid://140126511628363" -- square button and counter share it
UI.Assets.Pet = "rbxassetid://100296903679383"
UI.Assets.Trails = "rbxassetid://85706725966362"
UI.Assets.Inventory = "rbxassetid://81964370370028"
UI.Assets.Gifts = "rbxassetid://138549431513959"
UI.Assets.Trophy = "rbxassetid://92367166837958"
UI.Assets.Muscle = "rbxassetid://71232057538317" -- skill row and buy buttons share it
UI.Assets.Skill = UI.Assets.Muscle
UI.FallbackStuds = "rbxassetid://100359261064701"

local rgb = Color3.fromRGB
UI.Colors = {
	Red = rgb(255, 0, 49),
	ShopGold = rgb(255, 194, 0), -- Shop (Figma v3)
	CloseRed = rgb(249, 3, 96), -- popup close button, rebirth warning
	Green = rgb(77, 255, 0), -- REBIRTH
	Violet = rgb(170, 0, 255), -- SKIP
	ShadeSky = rgb(0, 119, 255),
	ShadeViolet = rgb(43, 0, 255),
	OfferGrey = rgb(217, 217, 217),
	Notify = rgb(255, 0, 0),
	Purple = rgb(238, 0, 255), -- Auras square
	Orange = rgb(255, 72, 0), -- Pets square
	Blue = rgb(0, 212, 255), -- level bar
	Yellow = rgb(255, 251, 0), -- +10M
	BuyRed = rgb(255, 0, 0), -- +100M
	Magenta = rgb(246, 0, 255), -- +1B
	-- shade overlays (colour, opacity at the bottom)
	ShadeBlack = rgb(0, 0, 0),
	ShadeRed = rgb(255, 0, 0),
	ShadeIndigo = rgb(64, 0, 255),
	ShadeBlue = rgb(0, 30, 255),
	-- text
	Gold = rgb(255, 226, 143), -- trophy counter
	Ice = rgb(220, 247, 255), -- rebirth counter
	Cream = rgb(255, 223, 160), -- skill row
	Track = rgb(255, 255, 255),
}

local function new(class: string, props: { [string]: any }?): any
	local o = Instance.new(class)
	local parent = nil
	for k, v in props or {} do
		if k == "Parent" then
			parent = v
		else
			(o :: any)[k] = v
		end
	end
	o.Parent = parent
	return o
end

local function corner(parent: Instance, px: number?)
	return new("UICorner", { CornerRadius = UDim.new(0, px or 12), Parent = parent })
end

-- White FredokaOne text with a dark outline. TextSize is the Figma size.
function UI.text(props: { [string]: any })
	local size = (props.TextSize or 36) * UI.TextScale
	local parent = props.Parent
	local holder = nil
	-- Shadow: Figma's drop shadow (black, 4px down). A child always draws over
	-- its parent, so the label and a black copy share a transparent holder
	-- (the holder takes the label's place in the layout; label.Parent is it).
	if props.Shadow then
		holder = new("Frame", {
			Name = props.Name or "Label",
			BackgroundTransparency = 1,
			Size = props.Size or UDim2.fromScale(1, 1),
			Position = props.Position or UDim2.new(),
			AnchorPoint = props.AnchorPoint or Vector2.zero,
			ZIndex = props.ZIndex or 5,
			Parent = parent,
		})
	end
	local function label(name, color, strokeColor, strokeT, z, pos)
		local t = new("TextLabel", {
			Name = name,
			BackgroundTransparency = 1,
			Font = UI.Font,
			Text = props.Text or "",
			TextColor3 = color,
			TextSize = size,
			TextXAlignment = props.TextXAlignment or Enum.TextXAlignment.Center,
			TextYAlignment = Enum.TextYAlignment.Center,
			Size = if holder then UDim2.fromScale(1, 1) else (props.Size or UDim2.fromScale(1, 1)),
			Position = if holder then pos else (props.Position or UDim2.new()),
			AnchorPoint = if holder then Vector2.zero else (props.AnchorPoint or Vector2.zero),
			ZIndex = z,
			Parent = holder or parent,
		})
		new("UIStroke", {
			Thickness = props.Stroke or math.max(2, size / 15),
			Color = strokeColor,
			Transparency = strokeT,
			LineJoinMode = Enum.LineJoinMode.Round,
			Parent = t,
		})
		return t
	end
	local z = props.ZIndex or 5
	local sh = nil
	if holder then
		sh = label("Shadow", Color3.new(0, 0, 0), Color3.new(0, 0, 0), 0, z, UDim2.fromOffset(0, 4))
	end
	local t = label(
		if holder then "Text" else (props.Name or "Label"),
		props.TextColor3 or Color3.new(1, 1, 1),
		props.StrokeColor or UI.TextOutline,
		props.StrokeTransparency or 0,
		if holder then z + 1 else z,
		UDim2.new()
	)
	if sh then
		t:GetPropertyChangedSignal("Text"):Connect(function()
			sh.Text = t.Text
		end)
	end
	return t
end

function UI.image(image: string?, props: { [string]: any })
	return new("ImageLabel", {
		Name = props.Name or "Icon",
		BackgroundTransparency = 1,
		Image = image or "",
		ScaleType = Enum.ScaleType.Fit,
		Size = props.Size,
		Position = props.Position or UDim2.new(),
		AnchorPoint = props.AnchorPoint or Vector2.zero,
		ZIndex = props.ZIndex or 4,
		Parent = props.Parent,
	})
end

--[[ The Figma face: fill + shade + studs + outline, on any GuiObject.
	style: Color, Shade (colour), ShadeFrom (0..1, where the shade starts),
	ShadeAlpha (opacity at the bottom), Studs (image), StudTile (px), StudAlpha,
	Alpha (fill opacity, default 1; the square buttons are black at 0.2) ]]
function UI.face(f: GuiObject, style)
	f.BackgroundColor3 = style.Color
	f.BackgroundTransparency = 1 - (style.Alpha or 1)
	f.BorderSizePixel = 0
	corner(f)
	new("UIStroke", {
		Thickness = 3,
		Color = Color3.new(0, 0, 0),
		Transparency = 0.5,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Parent = f,
	})
	-- Figma draws the outline inside the frame
	pcall(function()
		(f:FindFirstChildOfClass("UIStroke") :: any).BorderStrokePosition = Enum.BorderStrokePosition.Inner
	end)
	local shade = new("Frame", {
		Name = "Shade",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = style.Shade or UI.Colors.ShadeBlack,
		BorderSizePixel = 0,
		ZIndex = 2,
		Parent = f,
	})
	corner(shade)
	local from = style.ShadeFrom or 0.5
	local alpha = style.ShadeAlpha or 0.2
	local points = { NumberSequenceKeypoint.new(0, 1) }
	if from > 0 then
		table.insert(points, NumberSequenceKeypoint.new(from, 1))
	end
	table.insert(points, NumberSequenceKeypoint.new(1, 1 - alpha))
	new("UIGradient", { Rotation = 90, Transparency = NumberSequence.new(points), Parent = shade })
	local studs = style.Studs
	if studs == nil or studs == "" then
		studs = UI.FallbackStuds
	end
	local tile = style.StudTile or 89.4
	local s = new("ImageLabel", {
		Name = "Studs",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Image = studs,
		ScaleType = Enum.ScaleType.Tile,
		TileSize = UDim2.fromOffset(tile, tile),
		ImageTransparency = 1 - (style.StudAlpha or 0.4),
		ZIndex = 3,
		Parent = f,
	})
	corner(s)
	return f
end

-- A button is an invisible fixed-size slot (what layouts see and what takes the
-- clicks) holding a centred Visual with the face, content and PressScale. Hover
-- and press scale only the Visual, so it grows from its centre and never moves
-- its neighbours (like position: absolute). Put content in the returned Visual.
local function button(name: string, w: number, h: number, style)
	local b = new("TextButton", {
		Name = name,
		Text = "",
		AutoButtonColor = false,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.fromOffset(w, h),
		ZIndex = 1,
	})
	local v = new("Frame", {
		Name = "Visual",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromScale(1, 1),
		ZIndex = 1,
		Parent = b,
	})
	UI.face(v, style)
	new("UIScale", { Name = "PressScale", Parent = v })
	return b, v
end

local function finish(b: GuiObject, opts)
	if opts.Opens then
		b:SetAttribute("Opens", opts.Opens)
	end
	if opts.LayoutOrder then
		b.LayoutOrder = opts.LayoutOrder
	end
	b.Parent = opts.Parent
	return b
end

--[[ Rectangle button (Figma RectangleButton v2, 264x96): icon + label.
	opts: Name, Text, Icon, Color, Width, Parent, Opens ]]
function UI.rectButton(opts)
	local w = opts.Width or 264
	local b, v = button(opts.Name or "RectangleButton", w, 96, { Color = opts.Color or UI.Colors.Yellow, Studs = UI.Assets.Studs })
	-- icon 78px and label overlap by 12px; the pair is centred on the button
	local content = new("Frame", {
		Name = "Content",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(w - 40, 78),
		ZIndex = 4,
		Parent = v,
	})
	new("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		HorizontalAlignment = Enum.HorizontalAlignment.Center,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		Padding = UDim.new(0, -12),
		SortOrder = Enum.SortOrder.LayoutOrder,
		Parent = content,
	})
	local icon = UI.image(opts.Icon, { Parent = content, Size = UDim2.fromOffset(78, 78) })
	icon.LayoutOrder = 1
	local label = UI.text({ Name = "Label", Parent = content, Text = opts.Text or "Shop", TextSize = 36, Size = UDim2.fromOffset(0, 44) })
	label.AutomaticSize = Enum.AutomaticSize.X
	label.LayoutOrder = 2
	return finish(b, opts)
end

--[[ Square button (Figma SquareButton, 128x128): one 96px icon, optional label.
	opts: Name, Icon, Color, Text, Badge (text over the top edge),
	Notify (true or text: the red notification dot), Parent, Opens ]]
function UI.squareButton(opts)
	-- no Color: the Figma SquareButton (v3), a see-through face: black fill at
	-- 50%, black shade 0 -> 50% over the bottom half, pattern at 20%, 50% black outline
	local b, v = button(opts.Name or "SquareButton", 128, 128, {
		Color = opts.Color or Color3.new(0, 0, 0),
		Alpha = if opts.Color then 1 else 0.5,
		ShadeFrom = 0.5,
		ShadeAlpha = if opts.Color then 0.2 else 0.5,
		Studs = UI.Assets.StudsSquare,
		StudTile = 230,
		StudAlpha = 0.2,
	})
	UI.image(opts.Icon, {
		Parent = v,
		Size = UDim2.fromOffset(96, 96),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
	})
	if opts.Text and opts.Text ~= "" then
		UI.text({
			Parent = v,
			Text = opts.Text,
			TextSize = 30,
			Size = UDim2.new(1, 0, 0, 36),
			Position = UDim2.new(0.5, 0, 1, 2),
			AnchorPoint = Vector2.new(0.5, 1),
		})
	end
	if opts.Notify then
		UI.notification(v, if type(opts.Notify) == "string" then opts.Notify else "!")
	end
	-- Badge: Figma v3 "97%" on Rebirth, 36px, its box top 10px above the square
	if opts.Badge then
		UI.text({
			Name = "Badge",
			Parent = v,
			Text = opts.Badge,
			TextSize = 36,
			AnchorPoint = Vector2.new(0.5, 0),
			Position = UDim2.new(0.5, 4, 0, -10),
			Size = UDim2.new(1, 0, 0, 44),
			ZIndex = 6,
		})
	end
	return finish(b, opts)
end

--[[ Counter (Figma Counter v2): 70px icon + 36px amount at x=75, no background.
	opts: Name, Icon, Text, TextColor, Parent. Update counter.Amount.Text. ]]
function UI.counter(opts)
	local f = new("Frame", {
		Name = opts.Name or "Counter",
		BackgroundTransparency = 1,
		Size = UDim2.fromOffset(0, 70),
		AutomaticSize = Enum.AutomaticSize.X,
	})
	new("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		Padding = UDim.new(0, 5),
		SortOrder = Enum.SortOrder.LayoutOrder,
		Parent = f,
	})
	local icon = UI.image(opts.Icon, { Parent = f, Size = UDim2.fromOffset(70, 70) })
	icon.LayoutOrder = 1
	local amount = UI.text({
		Name = "Amount",
		Parent = f,
		Text = opts.Text or "0",
		TextSize = opts.TextSize or 36,
		TextColor3 = opts.TextColor or UI.Colors.Gold,
		Size = UDim2.fromOffset(0, 44),
		TextXAlignment = Enum.TextXAlignment.Left,
	})
	amount.AutomaticSize = Enum.AutomaticSize.X
	amount.LayoutOrder = 2
	return finish(f, opts)
end

--[[ Level progress (Figma Progress; QM widened it to 768 so the bar is 8:1): skill row on top, bar below.
	opts: Name, Skill, Multiplier, Level, Value, Fill (0..1), Parent.
	Children to update: SkillRow.SkillLabel, SkillRow.Multi, Bar.Level, Bar.Value,
	Bar.Fill (Size.X.Scale = progress). ]]
function UI.progress(opts)
	local f = new("Frame", {
		Name = opts.Name or "Progress",
		BackgroundTransparency = 1,
		Size = UDim2.fromOffset(opts.Width or UI.BarWidth, 161),
	})
	-- v2: 54px row, 54px icon, labels at y=12
	local row = new("Frame", { Name = "SkillRow", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 54), Parent = f })
	UI.image(UI.Assets.Skill, { Parent = row, Size = UDim2.fromOffset(54, 54) })
	UI.text({
		Name = "SkillLabel",
		Parent = row,
		Text = (opts.Skill or "1.2M") .. "  SKILL",
		TextSize = 32,
		TextColor3 = UI.Colors.Cream,
		TextXAlignment = Enum.TextXAlignment.Left,
		Position = UDim2.fromOffset(60, 12),
		Size = UDim2.new(0.5, 0, 0, 39),
	})
	UI.text({
		Name = "Multi",
		Parent = row,
		Text = (opts.Multiplier or "7x") .. " Multiplier",
		TextSize = 32,
		TextColor3 = UI.Colors.Cream,
		TextXAlignment = Enum.TextXAlignment.Right,
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 0, 0, 12),
		Size = UDim2.new(0.5, 0, 0, 39),
	})
	-- the bar: a white studded track with the blue Figma face as the fill
	local bar = new("Frame", { Name = "Bar", Position = UDim2.fromOffset(0, 65), Size = UDim2.new(1, 0, 0, 96), Parent = f })
	UI.face(bar, { Color = UI.Colors.Track, Shade = UI.Colors.ShadeBlack, ShadeFrom = 0.5, ShadeAlpha = 0.15, Studs = UI.Assets.Studs })
	local fill = new("Frame", {
		Name = "Fill",
		Size = UDim2.fromScale(math.clamp(opts.Fill or 1, 0, 1), 1),
		ZIndex = 4,
		Parent = bar,
	})
	UI.face(fill, { Color = UI.Colors.Blue, Shade = UI.Colors.ShadeBlue, ShadeFrom = 0, ShadeAlpha = 0.4, Studs = UI.Assets.Studs })
	UI.text({
		Name = "Level",
		Parent = bar,
		Text = "Level " .. tostring(opts.Level or 80),
		TextSize = 48,
		TextXAlignment = Enum.TextXAlignment.Left,
		Position = UDim2.fromOffset(22, 16),
		Size = UDim2.new(0.5, -22, 0, 58),
		ZIndex = 6,
	})
	UI.text({
		Name = "Value",
		Parent = bar,
		Text = opts.Value or "1.2k/3.05k",
		TextSize = 48,
		TextXAlignment = Enum.TextXAlignment.Right,
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -15, 0, 16),
		Size = UDim2.new(0.5, -15, 0, 58),
		ZIndex = 6,
	})
	return finish(f, opts)
end

--[[ Buy button (Figma BuyProgress, 181x74): arm icon popping out the top, big label.
	opts: Name, Text, Color, Shade, Price, Width, Parent ]]
function UI.buyButton(opts)
	local w = opts.Width or (UI.BarWidth - 2 * 16) / 3
	local b, v = button(opts.Name or "BuyButton", w, 74, {
		Color = opts.Color or UI.Colors.Yellow,
		Shade = opts.Shade or UI.Colors.ShadeRed,
		ShadeFrom = 0,
		ShadeAlpha = 0.4,
		Studs = UI.Assets.Studs,
	})
	UI.image(UI.Assets.Muscle, {
		Parent = v,
		-- Figma: 96px arm, top 22px above the top edge. Our upload keeps the
		-- image's soft transparent margin (the arm is only ~73% of the frame),
		-- which Figma's render crops, so the frame is 116px and starts 26px up
		-- to give the same visible arm (about 1.13x the button's height)
		Size = UDim2.fromOffset(116, 116),
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, -26),
	})
	UI.text({
		Name = "Label",
		Parent = v,
		Text = opts.Text or "+10M",
		TextSize = 36,
		-- label hangs ~13px below the bottom edge, as in Figma (box at 37, not
		-- 43: Roblox sets FredokaOne lower in its box than Figma does)
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 37),
		Size = UDim2.new(1, 0, 0, 44),
	})
	if opts.Price then
		UI.text({
			Name = "Price",
			Parent = v,
			Text = opts.Price,
			TextSize = 22,
			TextColor3 = rgb(140, 255, 120),
			TextXAlignment = Enum.TextXAlignment.Right,
			AnchorPoint = Vector2.new(1, 1),
			Position = UDim2.new(1, -8, 1, -2),
			Size = UDim2.fromOffset(60, 26),
		})
	end
	return finish(b, opts)
end

--[[ Modal: a general popup (shop, inventory, rebirth...) in the same face style.
	opts: Name, Title, Color, Visible, Parent. Returns the modal and its Content
	scrolling frame (a UIGridLayout is inside). ]]
function UI.modal(opts)
	local m = new("Frame", {
		Name = opts.Name or "Modal",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.45),
		-- fits two rows of five 128px cards; Content scrolls past that
		Size = UDim2.fromOffset(860, 452),
		Visible = opts.Visible ~= false,
		ZIndex = 10,
	})
	UI.face(m, { Color = opts.Color or UI.Colors.Blue, Shade = UI.Colors.ShadeBlue, ShadeFrom = 0, ShadeAlpha = 0.4, Studs = UI.Assets.Studs })
	UI.text({
		Name = "Title",
		Parent = m,
		Text = opts.Title or "Shop",
		TextSize = 64,
		TextXAlignment = Enum.TextXAlignment.Left,
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.fromOffset(28, 4),
		Size = UDim2.fromOffset(480, 80),
	})
	local close, closeVisual = button("Close", 72, 72, { Color = UI.Colors.Red, Studs = UI.Assets.Studs })
	close.AnchorPoint = Vector2.new(0.5, 0.5)
	close.Position = UDim2.new(1, -14, 0, 14)
	UI.text({ Name = "X", Parent = closeVisual, Text = "X", TextSize = 48 })
	close.Parent = m
	local body = new("Frame", {
		Name = "Body",
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, -24),
		Size = UDim2.new(1, -48, 1, -96),
		BackgroundColor3 = Color3.new(0, 0, 0),
		BackgroundTransparency = 0.75,
		ZIndex = 4,
		Parent = m,
	})
	corner(body)
	local content = new("ScrollingFrame", {
		Name = "Content",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		ScrollBarThickness = 8,
		ScrollBarImageColor3 = Color3.new(1, 1, 1),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		CanvasSize = UDim2.new(),
		ZIndex = 5,
		Parent = body,
	})
	new("UIPadding", {
		PaddingTop = UDim.new(0, 20),
		PaddingBottom = UDim.new(0, 20),
		PaddingLeft = UDim.new(0, 20),
		PaddingRight = UDim.new(0, 20),
		Parent = content,
	})
	new("UIGridLayout", {
		CellSize = UDim2.fromOffset(128, 128),
		CellPadding = UDim2.fromOffset(28, 28),
		HorizontalAlignment = Enum.HorizontalAlignment.Center,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Parent = content,
	})
	m.Parent = opts.Parent
	return m, content
end

--[[ Notification dot (Figma Gifts > Notification): 48px red circle, 50% black
	outline, white "!" (or a count), its top-left 31px in from the right edge and
	6px above the top. Parent it to a button's Visual so it scales with hover.
	Set dot.Visible / dot.Label.Text from code. ]]
function UI.notification(parent: GuiObject, text: string?)
	local dot = new("Frame", {
		Name = "Notification",
		BackgroundColor3 = UI.Colors.Notify,
		BorderSizePixel = 0,
		Position = UDim2.new(1, -31, 0, -6),
		Size = UDim2.fromOffset(48, 48),
		ZIndex = 7,
		Parent = parent,
	})
	corner(dot, 24)
	local st = new("UIStroke", { Thickness = 3, Color = Color3.new(0, 0, 0), Transparency = 0.5, Parent = dot })
	pcall(function()
		(st :: any).BorderStrokePosition = Enum.BorderStrokePosition.Inner
	end)
	UI.text({
		Name = "Label",
		Parent = dot,
		Text = text or "!",
		TextSize = 36,
		StrokeColor = Color3.new(0, 0, 0),
		StrokeTransparency = 0.5,
		Stroke = 3,
		ZIndex = 8,
	})
	return dot
end

-- the see-through face of the popups and square buttons (Figma v3 BG)
local GLASS = {
	Color = Color3.new(0, 0, 0),
	Alpha = 0.5,
	ShadeFrom = 0.5,
	ShadeAlpha = 0.5,
	StudAlpha = 0.2,
	StudTile = 230,
}

--[[ Popup (Figma "Popup" frames): see-through dark panel, 80px title over the
	top edge, a 192px icon breaking out of the top-left corner, and the red
	88px close button over the top-right corner. Hidden by default; a button
	with Opens = <Name> shows it (the controller closes other popups and blurs
	the world behind it). opts: Name, Title, Icon, Width, Height, IconOffset
	(Vector2, icon top-left relative to the panel), Visible, Parent.
	Returns the popup; put content straight into it (panel px coordinates). ]]
function UI.popup(opts)
	local w, h = opts.Width or 846, opts.Height or 621
	local p = new("Frame", {
		Name = opts.Name or "Popup",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(w, h),
		Visible = opts.Visible == true,
		ZIndex = 20,
	})
	p:SetAttribute("Popup", true)
	-- Figma draws black 50% over a white page, so the panel reads as mid grey;
	-- in game use that grey (nearly opaque) rather than black 50% over the world
	local panel = table.clone(GLASS)
	panel.Color = rgb(128, 128, 128)
	panel.Alpha = 0.92
	UI.face(p, panel)
	;(p:FindFirstChild("Studs") :: any).Image = UI.Assets.StudsSquare
	-- reference screenshots: the panel is ~57% of the screen height
	new("UIScale", { Name = "PopupScale", Scale = UI.PopupScale, Parent = p })
	local io = opts.IconOffset or Vector2.new(-57, -60)
	UI.image(opts.Icon, { Name = "Icon", Parent = p, Size = UDim2.fromOffset(192, 192), Position = UDim2.fromOffset(io.X, io.Y), ZIndex = 8 })
	UI.text({
		Name = "Title",
		Parent = p,
		Text = opts.Title or "Title",
		TextSize = 80,
		Shadow = true,
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, -55),
		Size = UDim2.new(1, -400, 0, 97),
		ZIndex = 9,
	})
	-- close: flat red, 20px corners, 50% black outline, white "x"
	local close, cv = button("Close", 88, 88, { Color = UI.Colors.CloseRed, ShadeAlpha = 0, StudAlpha = 0 })
	cv:FindFirstChildOfClass("UICorner").CornerRadius = UDim.new(0, 20)
	for _, c in cv:GetChildren() do
		if c:IsA("GuiObject") then
			c.Visible = false -- no shade or studs on the close button
		end
	end
	close.AnchorPoint = Vector2.new(1, 0)
	close.Position = UDim2.new(1, 30, 0, -29)
	close.ZIndex = 9
	UI.text({
		Name = "X",
		Parent = cv,
		Text = "x",
		TextSize = 64,
		StrokeColor = Color3.new(0, 0, 0),
		StrokeTransparency = 0.5,
		Stroke = 3,
		Position = UDim2.fromOffset(0, -6),
		ZIndex = 10,
	})
	close.Parent = p
	p.Parent = opts.Parent
	return p
end

-- a coloured face block (no button) at panel coordinates
local function block(parent, name, x, y, w, h, style)
	local f = new("Frame", { Name = name, Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(w, h), ZIndex = 4, Parent = parent })
	UI.face(f, style)
	return f
end

--[[ Shop offer placeholder (Figma Offer): light grey card, 3px black outline,
	white glow inside the edge. opts: Name, Height, LayoutOrder, Parent ]]
function UI.offer(opts)
	local f = new("Frame", {
		Name = opts.Name or "Offer",
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, opts.Height or 229),
		LayoutOrder = opts.LayoutOrder or 0,
		ZIndex = 4,
		Parent = opts.Parent,
	})
	-- the 3px black border sits on an overlay above the glow strips (a stroke
	-- on the card itself is drawn under its children and got covered)
	local border = new("Frame", {
		Name = "Border",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		ZIndex = 5,
		Parent = f,
	})
	local st = new("UIStroke", { Thickness = 3, Color = Color3.new(0, 0, 0), Parent = border })
	pcall(function()
		(st :: any).BorderStrokePosition = Enum.BorderStrokePosition.Inner
	end)
	-- Figma: grey fill with an inner shadow white, blur 16, spread 16: solid
	-- white for ~8px then fading to the grey by ~24px, on all four edges
	f.BackgroundColor3 = UI.Colors.OfferGrey
	for _, e in {
		{ "Top", UDim2.new(1, 0, 0, 26), UDim2.new(), 90 },
		{ "Bottom", UDim2.new(1, 0, 0, 26), UDim2.new(0, 0, 1, -26), 270 },
		{ "Left", UDim2.new(0, 26, 1, 0), UDim2.new(), 0 },
		{ "Right", UDim2.new(0, 26, 1, 0), UDim2.new(1, -26, 0, 0), 180 },
	} do
		local g = new("Frame", {
			Name = "Glow" .. e[1],
			BackgroundColor3 = Color3.new(1, 1, 1),
			BorderSizePixel = 0,
			Size = e[2],
			Position = e[3],
			ZIndex = 4,
			Parent = f,
		})
		new("UIGradient", {
			Rotation = e[4],
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0),
				NumberSequenceKeypoint.new(0.3, 0),
				NumberSequenceKeypoint.new(1, 1),
			}),
			Parent = g,
		})
	end
	return f
end

--[[ Shop popup (Figma 8:141): panel 1028x621, "~Section~" header and offer
	cards in a scrolling list. Returns popup, list (add more sections/offers). ]]
function UI.shopPopup(opts)
	local p = UI.popup({
		Name = opts.Name or "ShopPopup",
		Title = opts.Title or "Shop",
		Icon = UI.Assets.Shop,
		Width = 1028,
		Height = 621,
		IconOffset = Vector2.new(-41, -73),
		Visible = opts.Visible,
		Parent = opts.Parent,
	})
	local list = new("ScrollingFrame", {
		Name = "List",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(16, 103),
		Size = UDim2.new(1, -32, 1, -106),
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 0, -- Figma has no bar; it would cut the cards' edge
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ZIndex = 4,
		Parent = p,
	})
	new("UIListLayout", { Padding = UDim.new(0, 18), HorizontalAlignment = Enum.HorizontalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder, Parent = list })
	local sections = opts.Sections or { { Title = "~Section~", Offers = { 229, 195 } } }
	local order = 0
	for si, sec in sections do
		order += 1
		local title = UI.text({
			Name = "Section" .. si,
			Parent = list,
			Text = sec.Title,
			TextSize = 48,
			Shadow = true,
			Size = UDim2.new(1, 0, 0, 58),
			ZIndex = 6,
		})
		;(title.Parent :: Frame).LayoutOrder = order
		for oi, oh in sec.Offers do
			order += 1
			UI.offer({ Name = ("Offer%d_%d"):format(si, oi), Height = oh, LayoutOrder = order, Parent = list })
		end
	end
	return p, list
end

