-- LocalScript placed in the demo HUD: scales the HUD to the screen, animates
-- every button, wires Opens / Close, and runs the popup transitions.
UI.ControllerSource = [[
local TweenService = game:GetService("TweenService")
local Lighting = game:GetService("Lighting")
local Players = game:GetService("Players")
local gui = script.Parent
local camera = workspace.CurrentCamera

-- the layout is drawn at Figma size for a screen RefHeight px tall (sized so
-- the HUD takes the share of the screen it does in QM's layout reference)
local autoScale = gui:FindFirstChild("AutoScale")
local refHeight = gui:GetAttribute("RefHeight") or 1300
local refWidth = gui:GetAttribute("RefWidth") or 1625
local function rescale()
	if autoScale then
		local v = camera.ViewportSize
		autoScale.Scale = math.clamp(math.min(v.Y / refHeight, v.X / refWidth), 0.3, 1.6)
	end
end
camera:GetPropertyChangedSignal("ViewportSize"):Connect(rescale)
rescale()

local function tween(o, t, props, style, dir)
	local tw = TweenService:Create(o, TweenInfo.new(t, style or Enum.EasingStyle.Quad, dir or Enum.EasingDirection.Out), props)
	tw:Play()
	return tw
end

--------------------------------------------------------------------------------
-- Popups: glass background (blur + light tint), the HUD slides out to its
-- nearest edge (groups with a Slide attribute: Left / Right / Down) and the
-- popup pops in from its centre. Closing plays it backwards.
--------------------------------------------------------------------------------
local blur = Lighting:FindFirstChild("PopupBlur") or Instance.new("BlurEffect")
blur.Name = "PopupBlur"
blur.Size = 0
blur.Parent = Lighting

local glassGui = Instance.new("ScreenGui")
glassGui.Name = "PopupGlass"
glassGui.IgnoreGuiInset = true
glassGui.ResetOnSpawn = false
glassGui.DisplayOrder = gui.DisplayOrder - 1
local glass = Instance.new("Frame")
glass.Name = "Glass"
glass.Size = UDim2.fromScale(1, 1)
glass.BackgroundColor3 = Color3.fromRGB(235, 245, 255)
glass.BackgroundTransparency = 1
glass.BorderSizePixel = 0
glass.Parent = glassGui
glassGui.Parent = Players.LocalPlayer:WaitForChild("PlayerGui")

local slides = {}
for _, g in gui:GetDescendants() do
	local dir = g:GetAttribute("Slide")
	if dir and g:IsA("GuiObject") then
		local home = g.Position
		local away = if dir == "Left" then home - UDim2.fromScale(0.6, 0)
			elseif dir == "Right" then home + UDim2.fromScale(0.6, 0)
			else home + UDim2.fromScale(0, 0.6)
		table.insert(slides, { g = g, home = home, away = away })
	end
end

local popups = {}
for _, d in gui:GetDescendants() do
	if d:IsA("GuiObject") and d:GetAttribute("Popup") then
		local s = d:FindFirstChild("PopupScale")
		popups[d] = { scale = s, base = s and s.Scale or 1, open = d.Visible }
	end
end

local hudHidden = nil
local function refresh()
	local open = false
	for _, st in popups do
		open = open or st.open
	end
	if open == hudHidden then
		return
	end
	hudHidden = open
	tween(blur, 0.25, { Size = if open then 18 else 0 })
	tween(glass, 0.25, { BackgroundTransparency = if open then 0.8 else 1 })
	for _, sl in slides do
		if open then
			tween(sl.g, 0.3, { Position = sl.away }, Enum.EasingStyle.Back, Enum.EasingDirection.In)
		else
			tween(sl.g, 0.35, { Position = sl.home }, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
		end
	end
end

local closePopup
local function openPopup(p)
	local st = popups[p]
	for o, other in popups do
		if o ~= p and other.open then
			closePopup(o)
		end
	end
	st.open = true
	p.Visible = true
	if st.scale then
		st.scale.Scale = st.base * 0.2
		tween(st.scale, 0.35, { Scale = st.base }, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
	end
	refresh()
end
function closePopup(p)
	local st = popups[p]
	if not st.open then
		return
	end
	st.open = false
	if st.scale then
		local tw = tween(st.scale, 0.2, { Scale = st.base * 0.2 }, Enum.EasingStyle.Back, Enum.EasingDirection.In)
		tw.Completed:Connect(function()
			if not st.open then
				p.Visible = false
			end
		end)
	else
		p.Visible = false
	end
	refresh()
end

-- buttons: hover/press scale only the inner Visual (from its centre, nothing
-- else moves); Opens toggles a popup (or any frame); Close closes its parent
local function hook(b)
	if not b:IsA("GuiButton") then
		return
	end
	local visual = b:FindFirstChild("Visual")
	local s = visual and visual:FindFirstChild("PressScale")
	if s then
		local function to(v)
			tween(s, 0.08, { Scale = v })
		end
		b.MouseEnter:Connect(function() to(1.06) end)
		b.MouseLeave:Connect(function() to(1) end)
		b.MouseButton1Down:Connect(function() to(0.92) end)
		b.MouseButton1Up:Connect(function() to(1.06) end)
	end
	local opens = b:GetAttribute("Opens")
	if opens then
		b.Activated:Connect(function()
			local m = gui:FindFirstChild(opens, true)
			if m and popups[m] then
				if popups[m].open then
					closePopup(m)
				else
					openPopup(m)
				end
			elseif m then
				m.Visible = not m.Visible
			end
		end)
	end
	if b.Name == "Close" and b.Parent and b.Parent:IsA("GuiObject") then
		b.Activated:Connect(function()
			if popups[b.Parent] then
				closePopup(b.Parent)
			else
				b.Parent.Visible = false
			end
		end)
	end
end

for _, d in gui:GetDescendants() do
	hook(d)
end
gui.DescendantAdded:Connect(hook)
refresh()
]]

-- The HUD, laid out like QM's reference: Shop + square grid at the left,
-- counters bottom-left, skill/level bar with the three buy buttons bottom-centre.
function UI.buildHUD(parent: Instance, modalVisible: boolean?)
	local A, C = UI.Assets, UI.Colors
	local old = parent:FindFirstChild("HUD")
	if old then
		old.Parent = nil
	end
	local gui = new("ScreenGui", {
		Name = "HUD",
		ResetOnSpawn = false,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
	})
	local autoScale = new("UIScale", { Name = "AutoScale", Parent = gui })

	gui:SetAttribute("RefHeight", UI.RefHeight)
	gui:SetAttribute("RefWidth", UI.RefWidth)
	-- LocalScripts don't run in edit mode, so size it for the Studio viewport
	-- now and follow window resizes for this Studio session (the controller
	-- takes over in play)
	local cam = workspace.CurrentCamera
	if cam then
		autoScale.Scale = UI.fitScale(cam.ViewportSize)
		local G = _G :: any
		if G.__HUDFitConn then
			G.__HUDFitConn:Disconnect()
		end
		G.__HUDFitConn = cam:GetPropertyChangedSignal("ViewportSize"):Connect(function()
			if autoScale.Parent then
				autoScale.Scale = UI.fitScale(cam.ViewportSize)
			end
		end)
	end

	-- left: Shop over a 2x3 grid of see-through square buttons, 8px gaps. Positions
	-- are fractions of the screen taken from QM's reference screenshot.
	local left = new("Frame", {
		Name = "Left",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0, 0),
		Position = UDim2.new(0, 24, 0.306, 0), -- Shop top at 30.6% of the screen height
		Size = UDim2.fromOffset(264, 96 + 8 + 128 * 3 + 8 * 2),
		Parent = gui,
	})
	left:SetAttribute("Slide", "Left") -- slides off this way while a popup is open
	new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = left })
	UI.rectButton({ Name = "Shop", Text = "Shop", Icon = A.Shop, Color = C.ShopGold, Opens = "ShopPopup", LayoutOrder = 1, Parent = left })
	local grid = new("Frame", { Name = "Buttons", BackgroundTransparency = 1, Size = UDim2.fromOffset(264, 128 * 3 + 8 * 2), LayoutOrder = 2, ZIndex = 2, Parent = left })
	-- ZIndex 2: the Rebirth badge pokes up over the Shop button's bottom edge
	new("UIGridLayout", {
		CellSize = UDim2.fromOffset(128, 128),
		CellPadding = UDim2.fromOffset(8, 8),
		SortOrder = Enum.SortOrder.LayoutOrder,
		Parent = grid,
	})
	local squares = {
		{ "Auras", A.Aura },
		{ "Rebirth", A.Rebirth, "97%", "RebirthPopup" },
		{ "Pets", A.Pet },
		{ "Trails", A.Trails },
		{ "Inventory", A.Inventory },
		{ "Gifts", A.Gifts, nil, nil, true },
	}
	for i, sq in squares do
		UI.squareButton({ Name = sq[1], Icon = sq[2], Badge = sq[3], Opens = sq[4], Notify = sq[5], LayoutOrder = i, Parent = grid })
	end

	-- bottom-left: counters, trophy first (Figma v2), 8px apart
	local counters = new("Frame", {
		Name = "Counters",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 24, 1, -86), -- trophy bottom ~98 px above a 1488 px screen's edge
		Size = UDim2.fromOffset(240, 70 * 2 + 8),
		Parent = gui,
	})
	counters:SetAttribute("Slide", "Left") -- slides off this way while a popup is open
	new("UIScale", { Name = "GroupScale", Scale = UI.CounterScale, Parent = counters })
	new("UIListLayout", {
		Padding = UDim.new(0, 8),
		VerticalAlignment = Enum.VerticalAlignment.Bottom,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Parent = counters,
	})
	UI.counter({ Name = "Wins", Icon = A.Trophy, Text = "5K", TextColor = C.Gold, LayoutOrder = 1, Parent = counters })
	UI.counter({ Name = "Rebirths", Icon = A.Rebirth, Text = "2", TextColor = C.Ice, LayoutOrder = 2, Parent = counters })

	-- bottom-centre: skill + level bar, buy buttons under it (bottom ~48 px
	-- above the edge of a 1488 px screen, labels hanging into that margin)
	local bottom = new("Frame", {
		Name = "Bottom",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, -22), -- QM: closer to the bottom
		Size = UDim2.fromOffset(UI.BarWidth, 161 + 12 + 74),
		Parent = gui,
	})
	bottom:SetAttribute("Slide", "Down") -- slides off this way while a popup is open
	new("UIScale", { Name = "GroupScale", Scale = UI.BottomScale, Parent = bottom })
	UI.progress({ Name = "Progress", Skill = "1.2M", Multiplier = "7x", Level = 80, Value = "1.2k/3.05k", Fill = 0.39, Parent = bottom })
	local buys = new("Frame", {
		Name = "Buy",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.fromScale(0, 1),
		Size = UDim2.new(1, 0, 0, 74),
		ZIndex = 2,
		Parent = bottom,
	})
	new("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		HorizontalAlignment = Enum.HorizontalAlignment.Center,
		Padding = UDim.new(0, 16),
		SortOrder = Enum.SortOrder.LayoutOrder,
		Parent = buys,
	})
	UI.buyButton({ Name = "Buy10M", Text = "+10M", Color = C.Yellow, Shade = C.ShadeRed, LayoutOrder = 1, Parent = buys })
	UI.buyButton({ Name = "Buy100M", Text = "+100M", Color = C.BuyRed, Shade = C.ShadeIndigo, LayoutOrder = 2, Parent = buys })
	UI.buyButton({ Name = "Buy1B", Text = "+1B", Color = C.Magenta, Shade = C.ShadeIndigo, LayoutOrder = 3, Parent = buys })

	-- popups (Figma v3): Shop opens ShopPopup, the Rebirth square RebirthPopup
	UI.shopPopup({ Visible = modalVisible == true, Parent = gui })
	UI.rebirthPopup({ Parent = gui })

	local controller = Instance.new("LocalScript")
	controller.Name = "HUDController"
	;(controller :: any).Source = UI.ControllerSource
	controller.Parent = gui

	gui.Parent = parent
	return gui
end

-- Bare templates to :Clone() from code (ReplicatedStorage.UITemplates).
function UI.buildTemplates(parent: Instance)
	local A, C = UI.Assets, UI.Colors
	local old = parent:FindFirstChild("UITemplates")
	if old then
		old.Parent = nil
	end
	local folder = new("Folder", { Name = "UITemplates" })
	UI.rectButton({ Name = "RectangleButton", Text = "Shop", Icon = A.Shop, Color = C.Yellow, Parent = folder })
	UI.squareButton({ Name = "SquareButton", Icon = A.Aura, Parent = folder })
	UI.counter({ Name = "Counter", Icon = A.Trophy, Text = "5K", Parent = folder })
	UI.progress({ Name = "Progress", Parent = folder })
	UI.buyButton({ Name = "BuyButton", Text = "+10M", Parent = folder })
	UI.modal({ Name = "Modal", Title = "Title", Parent = folder })
	UI.popup({ Name = "Popup", Title = "Title", Icon = A.Shop, Parent = folder })
	UI.shopPopup({ Name = "ShopPopup", Parent = folder })
	UI.rebirthPopup({ Name = "RebirthPopup", Parent = folder })
	local n = new("Frame", { Name = "NotificationHolder", BackgroundTransparency = 1, Size = UDim2.fromOffset(128, 128), Parent = folder })
	UI.notification(n)
	folder.Parent = parent
	return folder
end

return UI

end

__modules["Template"] = function()
--[[
	Template: the reusable map + HUD template.

	    Template.build()  -- lighting + Cartoon Sky, Workspace.Map, StarterGui.HUD,
	                      -- ReplicatedStorage.UITemplates and ReplicatedStorage.UIKit

	Map.Settings and Colors hold every size and colour; Trees holds the
	per-biome tree variants; UI holds the HUD element builders.
]]

local Workspace = game:GetService("Workspace")
local ServerStorage = game:GetService("ServerStorage")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local StarterGui = game:GetService("StarterGui")

local Template = {}

Template.Colors = __require("Colors")
Template.Trees = __require("Trees")
Template.Map = __require("Map")
Template.UI = __require("UI")
Template.Sky = __require("Sky")
Template.Lighting = __require("Lighting")

-- Old showcase content and the original Baseplate move to ServerStorage so the
-- map has the place to itself (nothing is deleted).
local function tidy()
	local store = ServerStorage:FindFirstChild("TemplateSource")
	if not store then
		store = Instance.new("Folder")
		store.Name = "TemplateSource"
		store.Parent = ServerStorage
	end
	local bp = Workspace:FindFirstChild("Baseplate")
	if bp and not store:FindFirstChild("Baseplate") then
		bp.Parent = store
	end
	local show = Workspace:FindFirstChild("AssetShowcase")
	if show then
		show.Parent = store
	end
end

-- uiSource: the UI module's own source, so it can also live in the place as a
-- ModuleScript (the bundled command-bar script passes it in)
function Template.build(uiSource: string?)
	local L = Template.Lighting
	L.SkyAsset = nil
	L.ColorCorrection.Saturation = 0 -- colours are already fully saturated
	L.apply()
	Template.Sky.apply()

	Template.Map.build(Workspace)
	tidy()

	Template.UI.buildHUD(StarterGui)
	Template.UI.buildTemplates(ReplicatedStorage)
	if uiSource then
		local old = ReplicatedStorage:FindFirstChild("UIKit")
		if old then
			old.Parent = nil
		end
		local mod = Instance.new("ModuleScript")
		mod.Name = "UIKit"
		;(mod :: any).Source = uiSource
		mod.Parent = ReplicatedStorage
	end
end

return Template

end

__modules["Builder"] = function()
--[[
	Builder: low-level helpers for the studded blocky style.

	All parts are anchored matte SmoothPlastic in one flat colour, with QM's stud
	texture on every face ("studs"), an Inlet top ("inlet"), or no detail ("smooth"). Positions are given in the local
	space of an origin CFrame, so every asset can be built at any spot and rotation.
]]

local Palette = __require("Palette")

local Builder = {}

-- The grid texture laid over every studded face. It starts as the settings in
-- Palette.Baseplate and is replaced by the place's own Baseplate texture when
-- one exists (Builder.useGridFrom), so blocks get the same native checker grid.
Builder.Grid = {
	Texture = Palette.Baseplate.Texture,
	StudsPerTileU = Palette.Baseplate.StudsPerTile,
	StudsPerTileV = Palette.Baseplate.StudsPerTile,
	Transparency = Palette.Baseplate.TextureTransparency,
	Color3 = Palette.Baseplate.TextureColor,
}

function Builder.useGridFrom(tex: Texture)
	Builder.Grid = {
		Texture = tex.Texture,
		StudsPerTileU = tex.StudsPerTileU,
		StudsPerTileV = tex.StudsPerTileV,
		Transparency = if tex.Transparency >= 1 then Palette.Baseplate.TextureTransparency else tex.Transparency,
		Color3 = tex.Color3,
	}
end

-- QM's L-stud texture (Figma stud tile, same asset FightToStealAnEgg uses for
-- its HUD). Mostly transparent, so the part's own flat colour shows through.
-- One tile is 4x4 studs.
Builder.Studs = {
	Texture = "rbxassetid://100359261064701",
	StudsPerTile = 4,
	-- softens the L shadow so it reads like the reference instead of popping
	Transparency = 0.35,
}

local NORMALS = { Enum.NormalId.Top, Enum.NormalId.Bottom, Enum.NormalId.Left, Enum.NormalId.Right, Enum.NormalId.Front, Enum.NormalId.Back }

function Builder.addGrid(p: BasePart)
	local g = Builder.Grid
	for _, face in NORMALS do
		local t = Instance.new("Texture")
		-- unique names: Rojo can drop siblings that share a name when it syncs
		t.Name = "Grid" .. face.Name
		t.Face = face
		t.Texture = g.Texture
		t.StudsPerTileU = g.StudsPerTileU
		t.StudsPerTileV = g.StudsPerTileV
		t.Transparency = g.Transparency
		t.Color3 = g.Color3
		t.Parent = p
	end
end

-- Light-reactive studs: a MaterialVariant whose normal map (assets/studs, made
-- by tools/make_stud_maps.py) gives bright rims in sun and flat studs in shadow.
-- Decals can't react to light. Fill in the uploaded ids to switch every studded
-- part over; until then the decal is used.
Builder.StudMaterial = {
	Name = "AssetKitStuds",
	ColorMap = "", -- rbxassetid of assets/studs/stud_color.png
	NormalMap = "", -- rbxassetid of assets/studs/stud_normal.png
	StudsPerTile = 4,
}

local function studVariant(): string?
	local m = Builder.StudMaterial
	if m.ColorMap == "" or m.NormalMap == "" then
		return nil
	end
	local ms = game:GetService("MaterialService")
	if not ms:FindFirstChild(m.Name) then
		local v = Instance.new("MaterialVariant")
		v.Name = m.Name
		v.BaseMaterial = Enum.Material.SmoothPlastic
		v.ColorMap = m.ColorMap
		v.NormalMap = m.NormalMap
		v.StudsPerTile = m.StudsPerTile
		v.Parent = ms
	end
	return m.Name
end

function Builder.addStuds(p: BasePart)
	local variant = studVariant()
	if variant then
		p.Material = Enum.Material.SmoothPlastic
		p.MaterialVariant = variant
		return
	end
	local st = Builder.Studs
	for _, face in NORMALS do
		local t = Instance.new("Texture")
		t.Name = "Studs" .. face.Name
		t.Face = face
		t.Texture = st.Texture
		t.StudsPerTileU = st.StudsPerTile
		t.StudsPerTileV = st.StudsPerTile
		t.Transparency = st.Transparency
		-- white keeps the tile's rim highlight (QM wants it in sunlight; the
		-- engine's lighting dims it in shadow). Transparency keeps it from glowing.
		t.Color3 = Color3.new(1, 1, 1)
		t.Parent = p
	end
end

local FACES = { "TopSurface", "BottomSurface", "LeftSurface", "RightSurface", "FrontSurface", "BackSurface" }

-- "terrain": studs plus the native baseplate grid (walls, cliffs)
-- "studs": studs only, flat colour (trees, bushes, small obstacles)
type Style = "terrain" | "studs" | "inlet" | "smooth"

-- f > 0 lightens towards white, f < 0 darkens towards black.
function Builder.shade(c: Color3, f: number): Color3
	if f >= 0 then
		return c:Lerp(Color3.new(1, 1, 1), f)
	end
	return c:Lerp(Color3.new(0, 0, 0), -f)
end

function Builder.jitter(c: Color3, rng: Random, amount: number): Color3
	return Builder.shade(c, (rng:NextNumber() * 2 - 1) * amount)
end

function Builder.pick(list: { any }, rng: Random): any
	return list[rng:NextInteger(1, #list)]
end

function Builder.model(name: string, parent: Instance?, pivot: CFrame?): Model
	local m = Instance.new("Model")
	m.Name = name
	if pivot then
		m.WorldPivot = pivot
	end
	m.Parent = parent
	return m
end

function Builder.applyStyle(p: BasePart, style: Style?)
	style = style or "studs"
	-- studs come from QM's stud texture, not Roblox's SurfaceType.Studs
	for _, face in FACES do
		(p :: any)[face] = Enum.SurfaceType.Smooth
	end
	if style == "inlet" then
		p.TopSurface = Enum.SurfaceType.Inlet
	end
	-- obstacles are flat colour with studs only (QM): no grid texture, no checker.
	if style == "studs" or style == "terrain" then
		Builder.addStuds(p)
	end
	if style == "terrain" then
		-- walls and cliffs also carry the native baseplate grid
		Builder.addGrid(p)
	end
end

type PartOpts = {
	class: string?,
	name: string?,
	material: Enum.Material?,
	canCollide: boolean?,
	castShadow: boolean?,
	transparency: number?,
}

-- Raw part at a world CFrame.
function Builder.part(parent: Instance, size: Vector3, cf: CFrame, color: Color3, style: Style?, opts: PartOpts?): BasePart
	local o: PartOpts = opts or {}
	local p = Instance.new(o.class or "Part") :: BasePart
	p.Anchored = true
	p.Size = size
	p.CFrame = cf
	p.Color = color
	-- matte everywhere: flat SmoothPlastic with no reflectance
	p.Material = o.material or Enum.Material.SmoothPlastic
	p.Reflectance = 0
	Builder.applyStyle(p, style)
	p.CanCollide = o.canCollide ~= false
	p.CastShadow = o.castShadow ~= false
	if o.transparency then
		p.Transparency = o.transparency
	end
	-- unique sibling names keep Rojo syncs reliable
	p.Name = o.name or ("Block" .. (#parent:GetChildren() + 1))
	p.Parent = parent
	return p
end

-- Part centred at a local position relative to origin.
function Builder.box(parent: Instance, origin: CFrame, center: Vector3, size: Vector3, color: Color3, style: Style?, opts: PartOpts?): BasePart
	return Builder.part(parent, size, origin * CFrame.new(center), color, style, opts)
end

-- Part whose bottom face sits at local y = bottom.
function Builder.block(parent: Instance, origin: CFrame, x: number, bottom: number, z: number, size: Vector3, color: Color3, style: Style?, opts: PartOpts?): BasePart
	return Builder.box(parent, origin, Vector3.new(x, bottom + size.Y / 2, z), size, color, style, opts)
end

-- The texture the default Studio baseplate uses, applied to the top face.
function Builder.baseplateTexture(p: BasePart, settings)
	local t = Instance.new("Texture")
	t.Name = "BaseplateGrid"
	t.Face = Enum.NormalId.Top
	t.Texture = settings.Texture
	t.StudsPerTileU = settings.StudsPerTile
	t.StudsPerTileV = settings.StudsPerTile
	t.Transparency = settings.TextureTransparency
	t.Color3 = settings.TextureColor
	t.Parent = p
	return t
end

-- Floating name tag used by the showcase.
function Builder.label(adornee: Instance, text: string, height: number)
	local gui = Instance.new("BillboardGui")
	gui.Name = "ShowcaseLabel"
	gui.Size = UDim2.fromOffset(220, 40)
	gui.StudsOffsetWorldSpace = Vector3.new(0, height, 0)
	gui.AlwaysOnTop = true
	gui.MaxDistance = 160
	gui.Adornee = adornee
	local tl = Instance.new("TextLabel")
	tl.Size = UDim2.fromScale(1, 1)
	tl.BackgroundTransparency = 1
	tl.Font = Enum.Font.FredokaOne
	tl.TextScaled = true
	tl.TextColor3 = Color3.new(1, 1, 1)
	tl.TextStrokeTransparency = 0
	tl.Text = text
	tl.Parent = gui
	gui.Parent = adornee
	return gui
end

return Builder

end

__modules["Palette"] = function()
--[[
	Palette: one colour set per biome.

	Every generator in Kit reads colours from a palette table, so a new biome is
	mostly a new entry here plus a list of assets in its own module.
]]

local function rgb(r: number, g: number, b: number): Color3
	return Color3.fromRGB(r, g, b)
end

local Palette = {}

-- Fallback settings for the native baseplate look. Normally the ground is a
-- clone of the place's own Workspace.Baseplate, so these are not used.
Palette.Baseplate = {
	Texture = "rbxassetid://6372755229", -- only used if the place has no Baseplate to clone
	StudsPerTile = 8,
	TextureTransparency = 0.8,
	TextureColor = rgb(0, 0, 0),
	Thickness = 16,
}

-- Base / spawn area: olive yellow-green ground, yellow-green grass, purple-grey dirt.
Palette.Base = {
	Name = "Base",
	Ground = rgb(186, 189, 76),

	Grass = rgb(191, 195, 72),
	Dirt = rgb(126, 100, 110),

	Trunk = rgb(129, 105, 133),
	Leaves = { rgb(191, 195, 72), rgb(177, 184, 60), rgb(203, 206, 98), rgb(83, 148, 79) },

	Path = rgb(236, 196, 84),
	PathTrim = rgb(214, 206, 232),
}

-- Biome 1, Meadow: bright green grass, mauve-brown dirt cliffs, purple trunks.
Palette.Meadow = {
	Name = "Meadow",
	Ground = rgb(121, 183, 95),

	Grass = rgb(116, 178, 88),
	Dirt = rgb(132, 104, 115),

	Trunk = rgb(129, 105, 133),
	Leaves = { rgb(83, 148, 79), rgb(73, 140, 69), rgb(92, 154, 89) },

	Path = rgb(236, 196, 84),
	PathTrim = rgb(214, 206, 232),
}

return Palette

end

__modules["Lighting"] = function()
--[[
	Lighting: the bright, flat, low-contrast daylight look from the reference
	(crisp light shadows, no haze, no bloom, matte surfaces).
	Lighting.apply() sets the Lighting service and its post effects in place.
]]

local LightingService = game:GetService("Lighting")

local Lighting = {}

local function rgb(r: number, g: number, b: number): Color3
	return Color3.fromRGB(r, g, b)
end

-- Tuned in Studio against docs/reference (Nov 10): neutral grey ambient, equal
-- indoor and outdoor (trunks under a crown use Ambient), no sky tint on surfaces
-- (EnvironmentDiffuseScale 0), exposure 0 so the flat sky reads as in the reference.
-- Shadowed ground comes out about 77% of the lit ground, as there.
Lighting.Settings = {
	Technology = Enum.Technology.ShadowMap,
	Brightness = 2,
	ClockTime = 13,
	GeographicLatitude = 41.7,
	Ambient = rgb(170, 170, 170),
	OutdoorAmbient = rgb(170, 170, 170),
	ColorShift_Top = rgb(0, 0, 0),
	ColorShift_Bottom = rgb(0, 0, 0),
	GlobalShadows = true,
	ShadowSoftness = 0.2,
	EnvironmentDiffuseScale = 0,
	EnvironmentSpecularScale = 0, -- matte: no environment reflections
	ExposureCompensation = 0,
	FogStart = 100000,
	FogEnd = 100000,
}

Lighting.Atmosphere = {
	Density = 0.3,
	Offset = 0.25,
	Color = rgb(199, 212, 230),
	Decay = rgb(120, 150, 190),
	Glare = 0,
	Haze = 0.5,
}

Lighting.ColorCorrection = { Brightness = 0, Contrast = 0.05, Saturation = 0.3, TintColor = rgb(255, 255, 255) }

-- Realistic Sky (Creator Store 4607457995), loaded at build time; the flat
-- sky colour is the fallback if the insert fails (e.g. no permission).
Lighting.SkyAsset = 4607457995
Lighting.SkyTexture = "rbxassetid://81588505365795"

local function loadRealisticSky(): Sky?
	local ok, objs = pcall(function()
		return game:GetObjects("rbxassetid://" .. Lighting.SkyAsset)
	end)
	if not ok or not objs then
		return nil
	end
	for _, o in objs do
		local s = if o:IsA("Sky") then o else o:FindFirstChildWhichIsA("Sky", true)
		if s then
			return s :: Sky
		end
	end
	return nil
end

local function child(className: string, name: string): Instance
	local c = LightingService:FindFirstChildOfClass(className)
	if not c then
		c = Instance.new(className)
		c.Name = name
		c.Parent = LightingService
	end
	return c
end

function Lighting.apply()
	for k, v in Lighting.Settings do
		pcall(function()
			(LightingService :: any)[k] = v
		end)
	end
	-- no haze, glow, god rays or blur: the reference reads clean and flat
	for _, c in LightingService:GetChildren() do
		if c:IsA("BloomEffect") or c:IsA("SunRaysEffect") or c:IsA("DepthOfFieldEffect") or c:IsA("BlurEffect") then
			c.Enabled = false
		end
	end
	-- light distance haze: near things stay crisp, the far scene fades to blue-grey
	local atmosphere = child("Atmosphere", "Atmosphere") :: Atmosphere
	for k, v in Lighting.Atmosphere do
		(atmosphere :: any)[k] = v
	end
	-- SkyAsset = nil leaves the sky to the caller (the template loads AnimeSky)
	local realistic = if Lighting.SkyAsset then loadRealisticSky() else nil
	if realistic then
		for _, old in LightingService:GetChildren() do
			if old:IsA("Sky") then
				old.Parent = nil
			end
		end
		realistic.Name = "RealisticSky"
		realistic.Parent = LightingService
	elseif Lighting.SkyAsset then
		local sky = child("Sky", "Sky") :: Sky
		for _, face in { "SkyboxBk", "SkyboxDn", "SkyboxFt", "SkyboxLf", "SkyboxRt", "SkyboxUp" } do
			(sky :: any)[face] = Lighting.SkyTexture
		end
		sky.CelestialBodiesShown = false
		sky.StarCount = 0
	end
	local cc = child("ColorCorrectionEffect", "AssetKitColor") :: ColorCorrectionEffect
	for k, v in Lighting.ColorCorrection do
		(cc :: any)[k] = v
	end
	cc.Enabled = true
end

return Lighting

end

